    ('d120ca9a-703b-49e2-b333-ad6dfe508953'::uuid, 'unified_site_names', '3583736', 'site_id', '9983bdce-9f35-47a3-a570-4021cfa41b97', 'd120ca9a-703b-49e2-b333-ad6dfe508953', 'dup-merge-move-2026-11-05-rollback:unified_site_names:3583736:site_id', 'rollback of dup-merge-move-2026-11-05: unified_site_names.site_id of row 3583736 ''d120ca9a-703b-49e2-b333-ad6dfe508953'' restored for Ancient Kourion', 'Ancient Kourion | enwiki_title=Kourion, wikidata_qid=Q1785592 | retired | duplicate_of:9983bdce-9f35-47a3-a570-4021cfa41b97 | survivor Kourion | enwiki_title=Kourion, wikidata_qid=Q1785592', '[{"source": "identity/dup_judge.py, cluster retired-d120ca9a", "url": null, "quote": "MERGE ''Ancient Kourion'' into ''Kourion'': already retired as duplicate_of its survivor; its images and links still sit on it"}, {"source": "production:unified_sites", "url": null, "quote": "''Ancient Kourion'' (d120ca9a-703b-49e2-b333-ad6dfe508953): 20 image(s), 4 content link(s); survivor ''Kourion'' (9983bdce-9f35-47a3-a570-4021cfa41b97): 20 image(s), 5 content link(s); 469.4 m apart (read 2026-11-05 22:34:26.610072+00)"}]'::jsonb),
