    ('24676ed3-9308-42d4-bf35-1c739f0652e2'::uuid, 'unified_site_names', '3583738', 'site_id', '9d9d94a0-f338-4392-860f-983c29fabb16', '24676ed3-9308-42d4-bf35-1c739f0652e2', 'dup-merge-move-2026-11-05-rollback:unified_site_names:3583738:site_id', 'rollback of dup-merge-move-2026-11-05: unified_site_names.site_id of row 3583738 ''24676ed3-9308-42d4-bf35-1c739f0652e2'' restored for Archaeological Site, Heraion', 'Archaeological Site, Heraion | enwiki_title=Heraion of Perachora, wikidata_qid=Q2070087 | retired | duplicate_of:9d9d94a0-f338-4392-860f-983c29fabb16 | survivor Heraion of Perachora | enwiki_title=Heraion of Perachora, wikidata_qid=Q2070087', '[{"source": "identity/dup_judge.py, cluster retired-24676ed3", "url": null, "quote": "MERGE ''Archaeological Site, Heraion'' into ''Heraion of Perachora'': already retired as duplicate_of its survivor; its images and links still sit on it"}, {"source": "production:unified_sites", "url": null, "quote": "''Archaeological Site, Heraion'' (24676ed3-9308-42d4-bf35-1c739f0652e2): 20 image(s), 4 content link(s); survivor ''Heraion of Perachora'' (9d9d94a0-f338-4392-860f-983c29fabb16): 20 image(s), 5 content link(s); 122.1 m apart (read 2026-11-05 22:34:26.610072+00)"}]'::jsonb),
    ('3ebb514f-ac4a-4913-b54b-409bcc29eff4'::uuid, 'unified_site_names', '3584672', 'name_type', 'alias', 'label', 'dup-merge-move-2026-11-05-rollback:unified_site_names:3584672:name_type', 'rollback of dup-merge-move-2026-11-05: unified_site_names.name_type of row 3584672 ''label'' restored for Ancient Amathunta', 'Ancient Amathunta | enwiki_title=Amathus, wikidata_qid=Q2343313 | retired | duplicate_of:51daf6c9-25d3-4818-8857-0543f1203c57 | survivor Amathus | enwiki_title=Amathus, wikidata_qid=Q2343313', '[{"source": "identity/dup_judge.py, cluster retired-3ebb514f", "url": null, "quote": "MERGE ''Ancient Amathunta'' into ''Amathus'': already retired as duplicate_of its survivor; its images and links still sit on it"}, {"source": "production:unified_sites", "url": null, "quote": "''Ancient Amathunta'' (3ebb514f-ac4a-4913-b54b-409bcc29eff4): 17 image(s), 5 content link(s); survivor ''Amathus'' (51daf6c9-25d3-4818-8857-0543f1203c57): 17 image(s), 5 content link(s); 11.3 m apart (read 2026-11-05 22:34:26.610072+00)"}]'::jsonb),
    ('3ebb514f-ac4a-4913-b54b-409bcc29eff4'::uuid, 'unified_site_names', '3584672', 'site_id', '51daf6c9-25d3-4818-8857-0543f1203c57', '3ebb514f-ac4a-4913-b54b-409bcc29eff4', 'dup-merge-move-2026-11-05-rollback:unified_site_names:3584672:site_id', 'rollback of dup-merge-move-2026-11-05: unified_site_names.site_id of row 3584672 ''3ebb514f-ac4a-4913-b54b-409bcc29eff4'' restored for Ancient Amathunta', 'Ancient Amathunta | enwiki_title=Amathus, wikidata_qid=Q2343313 | retired | duplicate_of:51daf6c9-25d3-4818-8857-0543f1203c57 | survivor Amathus | enwiki_title=Amathus, wikidata_qid=Q2343313', '[{"source": "identity/dup_judge.py, cluster retired-3ebb514f", "url": null, "quote": "MERGE ''Ancient Amathunta'' into ''Amathus'': already retired as duplicate_of its survivor; its images and links still sit on it"}, {"source": "production:unified_sites", "url": null, "quote": "''Ancient Amathunta'' (3ebb514f-ac4a-4913-b54b-409bcc29eff4): 17 image(s), 5 content link(s); survivor ''Amathus'' (51daf6c9-25d3-4818-8857-0543f1203c57): 17 image(s), 5 content link(s); 11.3 m apart (read 2026-11-05 22:34:26.610072+00)"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 52;
    r        RECORD;
BEGIN
    -- expected is the plan's own cell count, rendered here, and not a second count of the
    -- temp table the loop below iterates (a tautology otherwise); apply_remediation_change
    -- raises unless exactly one row matched, this guard reports a loop that changed fewer.

    -- scope guard 1: every planned cell concerns a curated site, and the row it names exists
    -- and belongs to a curated site now
    SELECT count(*) INTO bad
      FROM _dup_merge_move_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds'
        OR NOT (CASE p.table_name WHEN 'wiki_images' THEN EXISTS (SELECT 1 FROM wiki_images t JOIN unified_sites o ON o.id = t.site_id WHERE t.id = p.row_id::integer AND o.source_id = 'ancient_nerds') WHEN 'site_content_links' THEN EXISTS (SELECT 1 FROM site_content_links t JOIN unified_sites o ON o.id = t.site_id WHERE t.id = p.row_id::integer AND o.source_id = 'ancient_nerds') WHEN 'unified_site_names' THEN EXISTS (SELECT 1 FROM unified_site_names t JOIN unified_sites o ON o.id = t.site_id WHERE t.id = p.row_id::integer AND o.source_id = 'ancient_nerds') ELSE false END);
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message
        RAISE EXCEPTION 'D14 duplicate move: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    SELECT count(*) INTO bad FROM _dup_merge_move_plan p
     WHERE p.new_value = '' OR CASE p.table_name || '.' || p.column_name
                WHEN 'wiki_images.site_id' THEN p.new_value::uuid IS NOT DISTINCT FROM p.old_value::uuid OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'wiki_images.is_hero' THEN p.new_value::boolean IS NOT DISTINCT FROM p.old_value::boolean OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'site_content_links.site_id' THEN p.new_value::uuid IS NOT DISTINCT FROM p.old_value::uuid OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'unified_site_names.site_id' THEN p.new_value::uuid IS NOT DISTINCT FROM p.old_value::uuid OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'unified_site_names.name_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR p.old_value IS NULL OR length(p.new_value) > 50
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned cell still holds the old value the plan names
    SELECT count(*) INTO bad FROM _dup_merge_move_plan p
     WHERE CASE p.table_name || '.' || p.column_name
                WHEN 'wiki_images.site_id' THEN (SELECT t.site_id FROM wiki_images t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.old_value::uuid
                WHEN 'wiki_images.is_hero' THEN (SELECT t.is_hero FROM wiki_images t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.old_value::boolean
                WHEN 'site_content_links.site_id' THEN (SELECT t.site_id FROM site_content_links t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.old_value::uuid
                WHEN 'unified_site_names.site_id' THEN (SELECT t.site_id FROM unified_site_names t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.old_value::uuid
                WHEN 'unified_site_names.name_type' THEN (SELECT t.name_type FROM unified_site_names t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned cell undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _dup_merge_move_plan p
     WHERE CASE p.table_name || '.' || p.column_name
                WHEN 'wiki_images.is_hero' THEN p.old_value NOT IN ('false')
                WHEN 'unified_site_names.name_type' THEN p.old_value NOT IN ('alias')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned site still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _dup_merge_move_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (u.name || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = u.id), '') || ' | ' || coalesce(u.scope_status, 'NULL') || ' | ' || coalesce(u.scope_reason, 'NULL') || ' | survivor ' || coalesce((SELECT s.name || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = s.id), '') FROM unified_sites s WHERE CAST(s.id AS text) = CASE CAST(u.id AS text) WHEN '04d8ce82-4fa3-4e48-88b7-bb41b354260c' THEN '00f522ff-8e1b-4983-961c-ef6cb1ff27d1' WHEN '07fb4e2f-26e5-4720-a949-9c28d4712e11' THEN '9152beea-f7ab-40ef-a692-ef63ac8e9ca6' WHEN '13c3f25f-3887-49c1-9492-cf7e512e5782' THEN '13120650-2e61-45af-976c-b2e0665c49af' WHEN '24676ed3-9308-42d4-bf35-1c739f0652e2' THEN '9d9d94a0-f338-4392-860f-983c29fabb16' WHEN '3ebb514f-ac4a-4913-b54b-409bcc29eff4' THEN '51daf6c9-25d3-4818-8857-0543f1203c57' WHEN '4687a49a-c987-4c56-bc6e-5094aa57667d' THEN 'c6d9487d-d138-4d73-beb1-5735e50da048' WHEN '4e6247b0-7416-413f-b7a3-b31890a45f3b' THEN '4a9b3802-1067-4f6b-a144-4c2ffe9619a4' WHEN '55a670ec-c7c5-4f52-98ea-b25211aedd4e' THEN '47c37ef9-98ee-41d8-879b-e78db06295da' WHEN '577b13cd-242b-4951-a8c4-ab3ecde0e5b1' THEN '23576019-c749-4ee9-95b1-cdae21f5ff06' WHEN '7e33b1ac-bb32-4b6c-b070-2c4fdcaf19fb' THEN '109fcdea-c114-4143-87ac-77c4c9c20f16' WHEN '8cecb38f-08cf-4a93-b350-9ccbb74109bb' THEN '5025eee3-28ea-46d6-b2c3-dbb1f38a24d6' WHEN '93391ee6-8e80-42db-922c-11f64ea57db9' THEN '84ef64f3-394a-4b35-ba4a-7e81b3b6a317' WHEN 'ab03fa75-bbdc-46a2-ba55-25e2f5edd5c4' THEN '485c3c0c-31f0-45a7-a06b-797c4c021466' WHEN 'ae2ca7b1-89da-46cb-8924-f9d04dd5da2e' THEN 'ce7db300-8777-425d-917a-2f6d9f325b58' WHEN 'b46b6969-3160-4cbd-a574-8727ee7c53c5' THEN '891ad351-7985-4c16-b6a6-830c26bc268f' WHEN 'd120ca9a-703b-49e2-b333-ad6dfe508953' THEN '9983bdce-9f35-47a3-a570-4021cfa41b97' WHEN 'dafc7527-c6c8-45c3-8c7d-4813d20a4dcf' THEN 'd41368ba-6aa2-4b75-adf4-8f2cd3cc7e4d' WHEN 'f23a31c3-6833-4df6-8583-3b3930b5a74f' THEN '21ac323f-7214-4891-9499-74e55c3d7d56' WHEN 'f3da4b6e-c4a3-4416-9c28-93bf761119ad' THEN '1531d4a1-bb24-4727-9b25-f2089088acaf' WHEN 'f5ca382a-3725-4cbb-961a-6afbf5c21507' THEN 'f6b6e039-36f1-4107-b730-dc2aa34b7a92' WHEN 'f967e3c4-fc5b-4cd0-91d1-06030d51e31c' THEN '0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3' END), '')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _dup_merge_move_plan ORDER BY table_name, row_id::integer, column_name LOOP
        moved := moved + apply_remediation_change(
            r.table_name, r.column_name, 'id', r.row_id,
            r.old_value, r.new_value,
            'D14/dup-merge-move', '2026-11-05_mechanical-dup-merge-move-rollback', r.change_key, 'two_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D14 duplicate move: % cell(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned cell now holds the new value
    SELECT count(*) INTO bad FROM _dup_merge_move_plan p
     WHERE CASE p.table_name || '.' || p.column_name
                WHEN 'wiki_images.site_id' THEN (SELECT t.site_id FROM wiki_images t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.new_value::uuid
                WHEN 'wiki_images.is_hero' THEN (SELECT t.is_hero FROM wiki_images t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.new_value::boolean
                WHEN 'site_content_links.site_id' THEN (SELECT t.site_id FROM site_content_links t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.new_value::uuid
                WHEN 'unified_site_names.site_id' THEN (SELECT t.site_id FROM unified_site_names t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.new_value::uuid
                WHEN 'unified_site_names.name_type' THEN (SELECT t.name_type FROM unified_site_names t WHERE t.id = p.row_id::integer) IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned cell(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, cell for cell, in both directions
    SELECT count(*) INTO bad
      FROM _dup_merge_move_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.row_id AND l.table_name = p.table_name
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-11-05_mechanical-dup-merge-move-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value
        OR l.site_id_ref IS DISTINCT FROM p.site_id;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: % planned cell(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-11-05_mechanical-dup-merge-move-rollback'
       AND (l.table_name || '.' || l.column_name NOT IN ('wiki_images.site_id', 'wiki_images.is_hero', 'site_content_links.site_id', 'unified_site_names.site_id', 'unified_site_names.name_type'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate move: this run stamp journalled % row(s) outside wiki_images.site_id, wiki_images.is_hero, site_content_links.site_id, unified_site_names.site_id, unified_site_names.name_type', bad;
    END IF;

    RAISE NOTICE 'D14 duplicate move: % of % planned cell(s) changed and journalled over 16 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-11-05_mechanical-dup-merge-move-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'D14/dup-merge-move'
UNION ALL
SELECT 'planned cells now holding the new value', count(*)::text
  FROM remediation_change_log p
 WHERE p.run_stamp = '2026-11-05_mechanical-dup-merge-move-rollback'
   AND (CASE p.table_name || '.' || p.column_name
                WHEN 'wiki_images.site_id' THEN (SELECT t.site_id FROM wiki_images t WHERE t.id = p.row_pk::integer) IS NOT DISTINCT FROM p.new_value::uuid
                WHEN 'wiki_images.is_hero' THEN (SELECT t.is_hero FROM wiki_images t WHERE t.id = p.row_pk::integer) IS NOT DISTINCT FROM p.new_value::boolean
                WHEN 'site_content_links.site_id' THEN (SELECT t.site_id FROM site_content_links t WHERE t.id = p.row_pk::integer) IS NOT DISTINCT FROM p.new_value::uuid
                WHEN 'unified_site_names.site_id' THEN (SELECT t.site_id FROM unified_site_names t WHERE t.id = p.row_pk::integer) IS NOT DISTINCT FROM p.new_value::uuid
                WHEN 'unified_site_names.name_type' THEN (SELECT t.name_type FROM unified_site_names t WHERE t.id = p.row_pk::integer) IS NOT DISTINCT FROM p.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'retired duplicates still holding an image or a content link', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND scope_status = 'retired' AND scope_reason LIKE 'duplicate_of:%' AND (EXISTS (SELECT 1 FROM wiki_images w WHERE w.site_id = unified_sites.id) OR EXISTS (SELECT 1 FROM site_content_links c WHERE c.site_id = unified_sites.id))
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
